function [e] = thrusters_empty(s)
%THRUSTERS_EMPTY  The thrusters with every couple failed: the tank is empty.
%   s: ThrusterSet (passed rec)
%   returns e: ThrusterSet (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    e = asils.models.thrusters.ThrusterSet_zero();
    e = s;
    j = ((0):((6) - 1)).';
    if ~isempty(j)
        e.failed((j) + 1) = true;
    end
end
